# owner: platform
import unittest
from datetime import date

from rosterkit.models import Mark, Student
from rosterkit.notices import absence_notice

PUPIL = Student("s1", "Lovelace", "Ada", "A")

def mark(when, status="absent", owner="s1"):
    return Mark(owner, date(2026, 9, when), status)

class NoticeTests(unittest.TestCase):
    def test_lists_dates_in_order(self):
        marks = [mark(9), mark(2), mark(4, "present")]
        self.assertEqual(
            absence_notice(PUPIL, marks),
            "Ada Lovelace missed 2 days: "
            "2026-09-02, 2026-09-09"
        )

    def test_single_day(self):
        text = absence_notice(PUPIL, [mark(2)])
        self.assertIn("1 day:", text)

    def test_other_student(self):
        marks = [mark(2), mark(3, owner="s2")]
        with self.assertRaises(ValueError):
            absence_notice(PUPIL, marks)

    def test_no_absences(self):
        with self.assertRaises(ValueError):
            absence_notice(PUPIL, [mark(2, "late")])
